// Authored NOT_RUN. Finite source identity is not rejected by metric overflow.
use kni_core::reference_slice::{Point,Span,ReferenceRing,ReferenceGlyph,preserve_reference,GlyphSliceResult,InternalBoundary};
use kni_core::decision_evidence_envelope::PinClaim;
fn glyph(spans:Vec<Span>)->ReferenceGlyph{ReferenceGlyph{glyph_id:"extreme".into(),source_pin:PinClaim{algorithm:"fixture".into(),claimed_digest:"unverified".into(),subject_ref:"extreme".into()},rings:vec![ReferenceRing{start:Point{x:1e200,y:1e200},spans}],declared_junction_decision_required:false}}
#[test]fn polygon_overflow_is_internal(){let o=Point{x:1e200,y:1e200};let g=glyph(vec![Span::Line{end:Point{x:-1e200,y:1e200}},Span::Line{end:Point{x:0.,y:-1e200}},Span::Line{end:o}]);match preserve_reference(g){GlyphSliceResult::Drawn{output,internal}=>{assert_eq!(output.rings.len(),1);assert!(internal.measurements[0].polygon_signed_area.is_none());assert!(internal.open_boundaries.iter().any(|b|matches!(b,InternalBoundary::PolygonAreaNumericallyUnresolved)));},_=>panic!("finite geometry must survive metric overflow")}}
#[test]fn curved_metric_overflow_does_not_refuse(){let o=Point{x:1e200,y:1e200};let g=glyph(vec![Span::Cubic{control_one:Point{x:0.,y:1e200},control_two:Point{x:-1e200,y:0.},end:Point{x:-1e200,y:1e200}},Span::Line{end:o}]);assert!(matches!(preserve_reference(g),GlyphSliceResult::Drawn{..}));}
